quests[65224] = { id = 65224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purchase 5 Unstable Flasks of the Beast for the cost of 50 Apexis Shards" }
quests[65284] = { id = 65284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Gumbo Kettle", sourceObjective = "Greetings {class}, I've been expecting you. An acquaintance of mine asked me to give you something when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose this item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[65285] = { id = 65285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Gumbo Kettle", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have this reward in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose this item, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[65561] = { id = 65561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabard of Flame", sourceObjective = "Greetings {class}, I've been expecting you. An acquaintance of mine asked me to give you something when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose this item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[65562] = { id = 65562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabard of Flame", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have this reward in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose this item, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[65593] = { id = 65593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hearts of the Lovers", description = "An incubus will be drawn to the hearts of lovers, and the most aching love will create the most irresistible lure.\n\nMy scrying has revealed two that should serve exceptionally.\n\nIn Silverpine Forest, Avelina Lilly provides her tailoring services to the fallen wizards at Ambermill. In the Barrens, Isaac Pearson hopes to make his mark in the seaside town of Ratchet.\n\nThey toil on opposite ends of the world, yet their hearts yearn only for each other. Bring those hearts to Carendin.", sourceObjective = "Bring the hearts of Avelina Lilly and Isaac Pearson to Carendin Halgar in the Temple of the Damned.", progress = "Ah, {name}, you return. Were you able to procure the lovers' hearts?", completion = "As expected. Excellently done, {name}.\n\n\n\nIdiots.", sourceObjectiveStatus = "unverified-source-field" }
quests[65597] = { id = 65597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "The time has come at last. Bring the hearts to the summoning circle below. Place them at its center and call forth the incubus.\n\nThe demon will not be pleased when it realizes that you have tempted it into a trap. Do not fall prey to its beguilement, {name}. You must subdue it fully.\n\nOnly then can I teach you the spell to bind it to your will.", sourceObjective = "Using the Lovers' Hearts, summon and subdue an incubus, then return the Lovers' Hearts to Carendin Halgar in the Magic Quarter of the Undercity.", progress = "The incubus possesses martial prowess, but its illusory charms are its most potent weapon. Falter for even a moment, and the demon will seize upon the opportunity to enthrall you.\n\nDo not let it, {name}.", completion = "Impressive. Very impressive. The sayaad specialize in preying upon mortals. Many a {class} has thought themselves strong enough to command one, only to find themselves being commanded instead.\n\nThis trial did not break you, {name}, and your efforts have earned your reward. I will teach you the spell to summon the incubus.", sourceObjectiveStatus = "unverified-source-field" }
quests[65601] = { id = 65601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love Hurts", description = "A sayaad male is known as an incubus. A creature of profound evil and singular mind.\n\nThe demon must be lured into our world with an item of enticement - an object that represents great love and devotion.\n\nIf you trust a blind man to lead you, {name}, then listen. East from the Cleft of Shadow, along the main drag of Orgrimmar, lives Magar. He longs for the return of his mate, Krilge.\n\nSeek him out. He'll ask you to search for something precious. That is the key which you must bring to Gan'rul.", sourceObjective = "Speak with Magar in Orgrimmar.", completion = "Who told you about Krilge? Have you come with any news? You better not be toying with me...", sourceObjectiveStatus = "unverified-source-field" }
quests[65602] = { id = 65602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Is Love?", description = "You will need a powerful reagent to tempt an incubus -- an object that represents great devotion and love.\n\nWith my scrying, I have located a small figurine that should be suitable for your ritual.\n\nThousands of years ago, the figurine belonged to a young couple. The original owners are no more, but their keepsake has survived to the present day.\n\nFollow the road north into Ashenvale, then west and past Maestra's Post. You will see a house nestled amongst the trees. There you will find what you seek.", sourceObjective = "Retrieve the Wooden Figurine and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.", progress = "You've returned. Successfully, I assume?", completion = "<Gakin turns the wooden figurine over in his hand.>\n\nI sense the emotional energy residing within this artifact, undiminished by the passing of time. The incubus will be drawn to it like a fly to honey.\n\nTakar never disappoints.", sourceObjectiveStatus = "unverified-source-field" }
quests[65603] = { id = 65603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "The time has come. Take the figurine and descend into the crypts below. A summoning circle has been prepared, and you must place the figurine at its center.\n\nThen the gateway will open, and the incubus will cross into our world.\n\nA sayaad is not to be underestimated. The demon will not hesitate to attack when it realizes your ruse. You must draw upon all you have been taught to defeat it.\n\nIf you succeed, return to me and I shall bind the creature to your will. Fail, and your soul is forfeit.", sourceObjective = "Using the Wooden Figurine, summon and subdue an incubus, then return the Wooden Figurine to Gakin the Darkbinder in the Slaughtered Lamb.", progress = "The incubus will try to lower your guard through beguilement and deception. The demon is adept at swaying the hearts of mortals.\n\nRemember that anything it may offer you is false. To the demon, you are merely prey.", completion = "Not bad, {name}. Your have bested the fiend, and your will remains unbroken.\n\nMany a {class} has believed themselves strong enough to bind a sayaad, only to become the demon's next meal instead. I am pleased to see you are not so foolish.\n\nWatch closely, and I will teach you the invocation to call upon your newly bound incubus.", sourceObjectiveStatus = "unverified-source-field" }
quests[65604] = { id = 65604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "Yes... I see. I feel the residual emotions bound within these threads. Love is woven into its stitches. The incubus will not be able to resist.\n\nTake this to the summoning circle in Neeru's tent, {name}. Summon forth a malevolent incubus, then show it your mastery. Do not expect it to be subdued quietly. Ready your magic and prepare yourself for a fight. Underestimating a demon has been many a warlock's final mistake.\n\nWhen you have defeated it, return the cloth to me. I will let Magar know what you found.", sourceObjective = "Using the Withered Scarf, summon and subdue an incubus, then return the Withered Scarf to Gan'rul Bloodeye in Orgrimmar.", progress = "The sayaad are dominators of minds and torturers of souls. Their visage brings the heart joy, leaving you defenseless when they rend your flesh with whip and claw.\n\nDo not entertain the incubus' charms, {name}. Slay it quickly and let it be done.", completion = "Hah! Victorious, as expected!\n\nThe incubus is subdued, and it will be my pleasure to teach you to summon the demon. Your strength is growing, and I have no doubt that this is a mere stepping stone to even greater powers.\n\nI will return the scarf to Magar. I have known that orc for many years, and never did I think he would care for someone the way he cared for Krilge.\n\nIt is a reminder of what separates us from the demons. We wield their darkness, but they will never wield us.", sourceObjectiveStatus = "unverified-source-field" }
quests[65610] = { id = 65610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wish You Were Here", description = "I met Krilge while making Mooncloth in Ashenvale. He was stationed there to protect civilians from danger, until he disappeared...\n\nThey've stopped looking for him and consider him a deserter, but I don't believe it.\n\nWe would often meet at Fallen Sky Lake before it became overrun by those aggressive bog beasts.\n\nI'm not typically one to ask favors, but if you could go to Ashenvale and look for any sign of him, I'd appreciate it.", sourceObjective = "Investigate Fallen Sky Lake in Ashenvale and report your findings to Gan'rul Bloodeye in Orgrimmar.", progress = "Yes, what is it?", completion = "What is it you have there, {name}? A scarf made of... Mooncloth? You best not be seeking to romance me.", sourceObjectiveStatus = "unverified-source-field" }
quests[91889] = { id = 91889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Reward has Arrived!" }
quests[93823] = { id = 93823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grand Delivery", sourceObjective = "Greetings {name}, I've been expecting you. An acquaintance of mine asked me to give you these items when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose an item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[93824] = { id = 93824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grand Delivery" }
quests[95158] = { id = 95158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reset Current Rating - 2v2", description = "Hey {name}, you're not looking too hot.\n\nRogues got you in a stun-lock? Mages chain polymorphing your arena partner?\n\nLook here, I may have a way to wipe this all off your record!\n\nFor the measly price of 40 gold, I can reset your Current Arena Rating for the 2v2 Bracket. This is a once a week deal that you won't want to miss!\n\nSo whaddya say?", sourceObjective = "Pay 40 gold to an Arena Organizer to reset Current 2v2 Arena Rating back to 1500.", completion = "You made the right choice, {name}... But let's just keep this between us for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[95251] = { id = 95251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reset Current Rating - 3v3", description = "Hey {name}, you're not looking too hot.\n\nRogues got you in a stun-lock? Mages chain polymorphing your arena partner?\n\nLook here, I may have a way to wipe this all off your record!\n\nFor the measly price of 40 gold, I can reset your Current Arena Rating for the 3v3 Bracket. This is a once a week deal that you won't want to miss!\n\nSo whaddya say?", sourceObjective = "Pay 40 gold to an Arena Organizer to reset Current 3v3 Arena Rating back to 1500.", sourceObjectiveStatus = "unverified-source-field" }
quests[95252] = { id = 95252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reset Current Rating - 5v5", description = "Hey {name}, you're not looking too hot.\n\nRogues got you in a stun-lock? Mages chain polymorphing your arena partner?\n\nLook here, I may have a way to wipe this all off your record!\n\nFor the measly price of 40 gold, I can reset your Current Arena Rating for the 5v5 Bracket. This is a once a week deal that you won't want to miss!\n\nSo whaddya say?", sourceObjective = "Pay 40 gold to an Arena Organizer to reset Current 5v5 Arena Rating back to 1500.", completion = "You made the right choice, {name}... But let's just keep this between us for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[95455] = { id = 95455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Concerted Efforts", description = "We're not fighting isolated battles against the Horde anymore, <lad/lass>.\n\nVictory in one front means denying the Horde resources they'd use against us in a different battle.  By the same token, abandoning any given battle could give the advantage to our opponent somewhere else around the world.\n\nThe Alliance is in need of more combatants with this sort of worldly understanding... truly seasoned veterans!  {name}, come back to me after you've served against the Horde at all of our active battlegrounds.", sourceObjective = "Bring 1 Alterac Valley Mark of Honor, 1 Arathi Basin Mark of Honor, 1 Warsong Gulch Mark of Honor and 1 Eye of the Storm Mark of Honor to an Alliance Brigadier General in any Alliance Capital City or Shattrath.", progress = "How are yer travels faring laddie?", completion = "You're not one to disappoint, {name}!  What you've learned goes beyond petty medals and commendations.  What you've learned is what can only come with experience and the hardening of one's temper in the field of battle.\n\nYou've done well, {class}.  You're a true hero of the Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[95456] = { id = 95456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Concerted Efforts", progress = "Ah, {name}.  I hope you continue to lend your experience to the different battlefronts.  A lot of our lads and lasses in the field look up to seasoned veterans like you.", completion = "You live up to yer reputation, {name}.  Without people like you, the Alliance wouldn't stand a chance against the savage forces of the Horde." }
quests[95457] = { id = 95457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Great Honor", description = "Serving the Horde in one of the great battles against the Alliance is a source of great honor!  The few however, that have served the Horde in ALL of our active battlefronts are our truly great fighters.  We shall vanquish our opponents, not by fighting isolated skirmishes, but by waging a well-coordinated war.\n\nGo forth and crush the Alliance in Arathi Basin, Alterac Valley, Eye of the Storm and Warsong Gulch!  For Honor!  For the Horde!", sourceObjective = "Bring 1 Alterac Valley Mark of Honor, 1 Arathi Basin Mark of Honor, 1 Warsong Gulch Mark of Honor and 1 Eye of the Storm Mark of Honor to a Horde Warbringer in any Horde capital city or Shattrath.", progress = "Arathi is still wet with the blood of great warriors and the clash of steel still rings throughout Alterac.  Do not waste my time unless you bring news from the front!", completion = "Your trials have not been easy, but your courage did not escape you and your strength did not fail.  Part with past tokens of victory, {class}.  None shall need them as a reminder of your worth.  Stand up straight, {name}.  Today you will walk with great pride for you are a hero!", sourceObjectiveStatus = "unverified-source-field" }
quests[95458] = { id = 95458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Great Honor", progress = "Many brave fighters look up to you, {name}.  You continue to be an example for all in the fight against the Alliance.  What news do you bring from your journeys?", completion = "You continue to honor the Horde, {name}.  I'm glad to see you haven't turned soft." }
quests[96253] = { id = 96253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unexpected Delivery", sourceObjective = "Greetings {name}, I've been expecting you. An acquaintance of mine asked me to give you these items when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose an item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[96254] = { id = 96254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unexpected Delivery" }
